/** Published LTBeamN results, not results generated by this repository.
 * Sources, section-property assumptions and comparison limits:
 * docs/composite-design/LTBEAM_COMPARISON.md.
 */
import { FORK, solveBeam, type LtbInput } from '../../../engineering/fem';

interface LtbeamReference {
  id: string;
  reference: number;
  /** Multiplies the load factor to give kNm, or 1 to compare load factors. */
  scale: number;
  scope: 'published-properties' | 'nominal-section';
  input: LtbInput;
}

export function ltbeamReferences(): LtbeamReference[] {
  const cases: LtbeamReference[] = [];
  const L = 5000, E = 210000, G = 81000;
  const properties = () => ({ EIz: E * 604e4, GIt: G * 20.7e4, EIw: E * 125900e6 });
  const paper: [string, 'point' | 'udl' | 'triangle', boolean, boolean, number][] = [
    ['2022-T6-1', 'point', false, false, 111.19],
    ['2022-T6-6', 'point', false, true, 87.76],
    ['2022-T6-31', 'point', true, false, 191.80],
    ['2022-T6-36', 'point', true, true, 167.43],
    ['2022-T7-1', 'udl', true, false, 177.22],
    ['2022-T7-6', 'udl', false, true, 124.34],
    ['2022-T7-7', 'triangle', true, false, 180.60],
    ['2022-T7-12', 'triangle', false, true, 146.70],
  ];
  for (const [id, kind, warping, fixed, reference] of paper) {
    const beam = solveBeam({ L, EI: () => E * 8360e4,
      supports: [0, L].map((x) => ({ x, w: true, theta: fixed })),
      loads: kind === 'point' ? { point: [{ x: L / 2, P: 1 }] }
        : { dist: [{ x1: 0, x2: L, q1: kind === 'udl' ? 1 : 0, q2: 1 }] },
    });
    // Independent statics: max |M| of a unit point/UDL/triangular load.
    const peak = kind === 'point' ? L / (fixed ? 8 : 4)
      : kind === 'udl' ? L ** 2 / (fixed ? 12 : 8)
      : L ** 2 / (fixed ? 20 : 9 * Math.sqrt(3));
    cases.push({ id, reference, scale: peak / 1e6, scope: 'published-properties', input: {
      L, props: properties, M: beam.M,
      supports: [0, L].map((x) => ({ ...FORK(x), phip: warping })),
      ...(kind === 'point' ? { pointLoads: [{ x: L / 2, Pzg: 150 }] }
        : { qzg: (x: number) => 150 * (kind === 'udl' ? 1 : x / L) }),
    } });
  }
  // CTICM 2013, Set 80. The report gives dimensions but does not tabulate
  // Iz/It/Iw for this set. Explicitly use nominal thin-wall plate properties.
  const span = 18000, h = 500, b = 280, tf = 19, tw = 12.5, hw = h - 2 * tf;
  const nominal = () => ({
    EIz: E * (2 * tf * b ** 3 / 12 + hw * tw ** 3 / 12),
    GIt: E / 2.6 * (2 * b * tf ** 3 + hw * tw ** 3) / 3,
    EIw: E * tf * b ** 3 * (h - tf) ** 2 / 24,
  });
  const restraints: [string, number, number[], { x: number; z: number }[]][] = [
    ['80', 6.9985, [span / 2], []],
    ['82', 5.1275, [span / 4], []],
    ['83', 10.0969, [span / 4, 3 * span / 4], []],
    ['84-1', 5.1275, [], [{ x: span / 4, z: h / 2 }]],
    ['84-2', 4.7482, [], [{ x: span / 4, z: 0 }]],
    ['84-3', 2.9840, [], [{ x: span / 4, z: -h / 2 }]],
  ];
  for (const [id, reference, forks, flangeRestraints] of restraints) cases.push({
    id: `2013-${id}`, reference, scale: 1, scope: 'nominal-section', input: {
      L: span, props: nominal, M: (x) => 3 * x * (span - x) / 2,
      restraints: forks, flangeRestraints,
    },
  });
  // CTICM 2013 section 5, P1-6A. Web height (not total depth) = 400 -> 800.
  // LTBeamN uses Vilette torsion there; ours is explicitly thin-wall, so these
  // remain nominal comparisons, not an assertion of identical taper theories.
  for (const [length, reference] of [[5000, 7.722], [10000, 2.611]]) cases.push({
    id: `2013-P1-6A-${length / 1000}m`, reference, scale: 1, scope: 'nominal-section', input: {
      L: length, M: () => 200e6, props: (x) => {
        const web = 400 + 400 * x / length, width = 250, flange = 20, wall = 14;
        return {
          EIz: E * (2 * flange * width ** 3 / 12 + web * wall ** 3 / 12),
          GIt: E / 2.6 * (2 * width * flange ** 3 + web * wall ** 3) / 3,
          EIw: E * flange * width ** 3 * (web + flange) ** 2 / 24,
        };
      },
    },
  });
  return cases;
}
